#if FRAMEJOB_DEV_TOOLS
/// `tutorial_start`, `tutorial_state`, `tutorial_step` and `tutorial_exit` —
/// dev tools (spec §11 TU-8, V-1..V-2): drive a project window's tutorial
/// runner (`TutorialRunner`) with no chrome, so `tutorial_proof.py` can run
/// the guide's tutorials as a person and by Show Me alone. The product's door
/// is TU3's coach panel and Help ▸ Tutorials.
///
/// Every answer but a refusal is the runner's state, `{ok, project,
/// running}` and, while one runs, `TutorialRunner.state()`. A refusal — no
/// editor window, an unknown or refused id, unmet needs, a move the step does
/// not offer — is the runner's own sentence.
///
/// `tutorial_start`, `tutorial_state` and `tutorial_exit` run on MAIN.
/// `tutorial_start`'s answer is made in its own main block, so it shows step
/// 1; the start's evaluation runs on a later main turn, before any later
/// tool's main block (the main queue is first in, first out).
/// `tutorial_step` runs on the SERVER thread (`devOffMainTools`): `show_me`
/// presses Show Me on main, then waits WITHOUT the lane's lock
/// (`AgentLane.releasingLock`, as `assistant_send` does), reading the
/// runner on main every 50 ms for up to 60 s, because Show Me's own calls go
/// through the lane's `submit` and need the lock.
extension AgentServer {

    func tutorialStart(_ a: [String: Any]) throws -> String {
        guard let id = try stringArg(a, "id") else {
            throw ToolError(message: "Missing required argument: id")
        }
        let (editor, project) = try tutorialEditor(a)
        let library: TutorialLibrary
        do {
            library = try TutorialLibrary.bundled()
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        if let reason = library.refused[id] {
            throw ToolError(message: "The tutorial \(id) does not read: \(reason).")
        }
        guard let tutorial = library.tutorial(id: id) else {
            throw ToolError(
                message: "No tutorial is called \(id); the tutorials are "
                    + library.ids.joined(separator: ", ") + ".")
        }
        do {
            try TutorialRunner.start(tutorial, in: editor)
        } catch let refusal as TutorialRefusal {
            throw ToolError(message: refusal.sentence)
        }
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialState(_ a: [String: Any]) throws -> String {
        let (editor, project) = try tutorialEditor(a)
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialExit(_ a: [String: Any]) throws -> String {
        let (editor, project) = try tutorialEditor(a)
        guard let runner = editor.tutorialRunner else {
            throw ToolError(message: Self.noTutorial)
        }
        runner.exit()
        return try jsonResult(Self.tutorialAnswer(editor, project))
    }

    func tutorialStep(_ a: [String: Any]) throws -> String {
        guard let action = try stringArg(a, "action") else {
            throw ToolError(message: "Missing required argument: action")
        }
        guard Self.tutorialActions.contains(action) else {
            throw ToolError(
                message: "action must be show_me, next, back or skip (got \"\(action)\").")
        }
        // This thread holds the editor and the runner only weakly, so it never
        // keeps either alive past an exit or a start while the lock is out.
        weak var watchedEditor: EditorViewController?
        weak var watchedRunner: TutorialRunner?
        let project = try onMain { () throws -> Any in
            let (editor, project) = try self.tutorialEditor(a)
            guard let runner = editor.tutorialRunner else {
                throw ToolError(message: Self.noTutorial)
            }
            do {
                switch action {
                case "show_me": try runner.showMe()
                case "next": try runner.next()
                case "back": try runner.back()
                default: try runner.skip()
                }
            } catch let refusal as TutorialRefusal {
                throw ToolError(message: refusal.sentence)
            }
            watchedEditor = editor
            watchedRunner = runner
            return project
        }
        if action == "show_me" {
            let started = Date()
            AgentLane.shared.releasingLock {
                while Date().timeIntervalSince(started) < Self.showMeTimeout {
                    let running = onMain { () -> Bool in
                        guard let editor = watchedEditor, let runner = watchedRunner else {
                            return false
                        }
                        return editor.tutorialRunner === runner && runner.showMeRunning
                    }
                    guard running else { break }
                    Thread.sleep(forTimeInterval: 0.05)
                }
            }
        }
        return try jsonResult(
            onMain { () throws -> [String: Any] in
                let (editor, _) = try self.tutorialEditor(a)
                return Self.tutorialAnswer(editor, project)
            })
    }

    private static let tutorialActions: Set<String> = ["show_me", "next", "back", "skip"]
    private static let showMeTimeout = 60.0
    private static let noTutorial =
        "No tutorial is running in this window: tutorial_start starts one."

    /// The project's editor and its path for the answer, refused as
    /// `select_inspector_tab` refuses a windowless project. Main thread.
    private func tutorialEditor(_ a: [String: Any]) throws -> (EditorViewController, Any) {
        let document = try target(a)
        guard let editor = editor(document), editor.isViewLoaded else {
            let name = Self.path(of: document) ?? document.displayName ?? "Untitled"
            throw ToolError(
                message: "The project \(name) has no window: a tutorial runs only in its editor "
                    + "window.")
        }
        return (editor, UISnapshot.orNull(Self.path(of: document)))
    }

    /// The state every tool answers. Main thread.
    private static func tutorialAnswer(_ editor: EditorViewController, _ project: Any)
        -> [String: Any] {
        var answer: [String: Any] = ["ok": true, "project": project, "running": false]
        if let runner = editor.tutorialRunner {
            answer.merge(runner.state()) { _, theirs in theirs }
        }
        return answer
    }

    // MARK: - Catalog

    func tutorialStartTool() -> [String: Any] {
        tool(
            "tutorial_start",
            "DEV TOOL (absent from Distribution builds). Start a guide tutorial by id in a "
                + "project's editor window, replacing any tutorial running there: its needs are "
                + "checked first and, when no clip meets them, the call is refused with the "
                + "sentence naming what is missing. Answers the runner's state at step 1: ok, "
                + "project, running and, while running, id, title, step (1-based), steps, text, "
                + "optional, wait, show_me, offers (of back, show_me, skip, next, exit), "
                + "spotlight, reveal {tab, sub_tab, section} or null, reveal_refused, finished, "
                + "show_me_running, last_show_me {step, ok, error, results, paths} or null, "
                + "selection_at_start, created and completed [{step, by}]. A wait already met "
                + "advances on a later main turn. Refused: an unknown id (the refusal lists the "
                + "tutorials), a tutorial the model does not read (with its reason) and a project "
                + "with no window.",
            [
                "id": [
                    "type": "string",
                    "description": "The tutorial's id, as its guide page names it "
                        + "(audio.volume, editing.split, …).",
                ]
            ],
            required: ["id"])
    }

    func tutorialStateTool() -> [String: Any] {
        tool(
            "tutorial_state",
            "DEV TOOL (absent from Distribution builds). Answer the state of the tutorial "
                + "running in a project's editor window, changing nothing: running false when "
                + "none runs, else the fields tutorial_start answers.",
            [:])
    }

    func tutorialStepTool() -> [String: Any] {
        tool(
            "tutorial_step",
            "DEV TOOL (absent from Distribution builds). Press one of the running tutorial's "
                + "buttons: show_me runs the step's Show Me — its tool calls through the "
                + "assistant's lane with ordinary undo, its menu items through the menu bar's "
                + "own validated item — and answers once it has finished (up to 60 s), its "
                + "outcome in last_show_me; next goes on from a step with no wait; back re-begins "
                + "the step before (or the last, once finished) and does not evaluate it; skip "
                + "passes an optional step. Answers the state. Refused in the runner's own "
                + "sentence: a move the step does not offer, and no tutorial running.",
            [
                "action": [
                    "type": "string", "enum": ["show_me", "next", "back", "skip"],
                    "description": "The button: show_me, next, back or skip.",
                ]
            ],
            required: ["action"])
    }

    func tutorialExitTool() -> [String: Any] {
        tool(
            "tutorial_exit",
            "DEV TOOL (absent from Distribution builds). End the tutorial running in a "
                + "project's editor window, undoing nothing. Answers the state (running false). "
                + "Refused when no tutorial runs there.",
            [:])
    }
}
