import AppKit

/// The inspector reached by name from outside it: the pane it shows, a
/// section scrolled to the top, the Clip pane, and a tutorial step's reveal
/// (spec §11 TU-8 (6)). `shownPane`, `scroll(to:)` and `clipPane` were
/// `select_inspector_tab`'s (`AgentServer+InspectorTab.swift`), moved here
/// whole so the runner, which is product code, can reach them. Main only.
extension InspectorViewController {
    /// The scroll view the inspector shows its pane in, and that pane.
    func shownPane() -> (NSScrollView, InspectorPaneView)? {
        var queue: [NSView] = [view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let scroll = view as? NSScrollView, let pane = scroll.documentView as? InspectorPaneView {
                return (scroll, pane)
            }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    /// Scrolls the shown pane so section `id`'s top is the visible top,
    /// clamped to the pane; refused, naming the sections it holds, when it
    /// holds no such section. Writes no preference and opens nothing.
    func scroll(to id: String) throws {
        let shown = shownPane()
        let sections = shown?.1.sections ?? []
        guard let (scroll, pane) = shown, let section = sections.first(where: { $0.id == id })
        else {
            let ids = sections.map(\.id)
            throw AgentServer.ToolError(
                message: "The shown pane has no section \(id); its sections are "
                    + (ids.isEmpty ? "none" : ids.joined(separator: ", ")) + ".")
        }
        view.layoutSubtreeIfNeeded()
        let clip = scroll.contentView
        let top = section.convert(section.bounds, to: pane).minY
        let bottom = max(0, pane.frame.height - clip.bounds.height)
        clip.scroll(to: NSPoint(x: 0, y: min(max(0, top), bottom)))
        scroll.reflectScrolledClipView(clip)
    }

    /// The Clip pane among the inspector's descendants — there only while the
    /// Clip tab shows it.
    func clipPane() -> ClipPane? {
        var queue: [NSView] = [view]
        while !queue.isEmpty {
            let view = queue.removeFirst()
            if let pane = view as? ClipPane { return pane }
            queue.append(contentsOf: view.subviews)
        }
        return nil
    }

    /// A tutorial step's reveal through the clicks' own paths: the tab, the
    /// sub-tab when the selection offers it, the section opened by
    /// `InspectorSection.reveal()` (which writes no preference), then
    /// scrolled to the top. nil, or the sentence saying what could not be
    /// shown.
    func reveal(_ r: TutorialReveal) -> String? {
        select(r.tab)
        if let sub = r.subTab {
            let offered = clipPane()?.subTabs ?? []
            guard !selectedClips.isEmpty, offered.contains(sub) else {
                return "The selection has no \(sub.title) sub-tab."
            }
            selectClipSubTab(sub)
        }
        guard let id = r.section else { return nil }
        guard let section = shownPane()?.1.sections.first(where: { $0.id == id }) else {
            return "The inspector shows no \(id) section now."
        }
        section.reveal()
        do {
            try scroll(to: id)
        } catch let error as AgentServer.ToolError {
            return error.message
        } catch {
            return error.localizedDescription
        }
        return nil
    }

    /// The shown pane's sections whose frame meets the visible rect, top to
    /// bottom.
    func visibleSectionIDs() -> [String] {
        guard let (_, pane) = shownPane() else { return [] }
        view.layoutSubtreeIfNeeded()
        let visible = pane.visibleRect
        return pane.sections.filter { section in
            let frame = section.convert(section.bounds, to: pane)
            return frame.height > 0 && frame.intersects(visible)
        }.map(\.id)
    }

    /// The shown pane's open sections, top to bottom.
    func expandedSectionIDs() -> [String] {
        (shownPane()?.1.sections ?? []).filter(\.isExpanded).map(\.id)
    }
}
